from PIL import Image
import numpy as np,json
for f in ['clear','align2','grasp2','lift2']:
 m=json.load(open('/app/output/'+f+'/meta.json'));print('\n',f)
 for cam in ['front','side','top']:
  a=np.array(Image.open('/app/output/'+f+'/last/'+cam+'.jpg'));d=np.load('/app/output/'+f+'/depth_'+cam+'.npy');d=d[-1] if d.ndim==3 else d
  Y,X=np.indices(d.shape)
  if cam=='front':roi=(X>130)&(X<210)&(Y>75)&(Y<130)
  elif cam=='side':roi=(X>90)&(X<180)&(Y>75)&(Y<130)
  else:roi=(X>115)&(X<190)&(Y>70)&(Y<135)
  mask=roi&(a.mean(2)>185)&((a.max(2).astype(float)-a.min(2))<30)&(d>.7)&(d<1.1)
  xx=X[mask];yy=Y[mask];dd=d[mask].astype(float)
  K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);cs=np.array([(xx-160)*dd/K[0,0],-(yy-120)*dd/K[1,1],-dd,np.ones(len(dd))]).T;w=(T@cs.T).T[:,:3]
  if len(w):print(cam,len(w),np.round(np.median(w,axis=0),3),np.round(np.quantile(w,[.1,.9],axis=0),3))
